"""Build a static offline index, source ledger, exact gap inventory and assigned report."""
from pathlib import Path
import collections,datetime,gzip,hashlib,html,json,re
from county_notes import NOTES
R=Path(__file__).resolve().parent
j=lambda f:json.loads((R/f).read_text())
w=lambda f,x:(R/f).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
h=html.escape
D=j('dataset-manifest.json');P=j('pdf-manifest.json');C=j('county-inventory.json');priority=[c for c in C if c['priority']];assert len(priority)==len(NOTES)==32
# Supplemental ward/school maps are downloadable evidence but not counted as precinct packages.
for p in P:
 p['asset_class']='precinct-map'
 if p['county']=='lorain' and (not p['label'].replace('\u200b','').strip() or 'ward-map supplement' in p['label']):p['asset_class']='ward-map-supplement';p['label']='Grafton Village ward-map supplement (2023)'
 if p['county']=='wayne' and 'School' in p['label']:p['asset_class']='school-district-supplement'
 if p['county']=='summit':p['asset_class']='historical-council-map-with-precinct-lines'
 p['approval_nov2026']='not established';p['crosswalk_2026']='not validated'
w('pdf-manifest.json',P)
# Actual file format, not misleading source catalog title.
image=dict(county='ashtabula',path='evidence/continued/ashtabula-pdf.bin',format='JPEG',width=816,height=1056,printed_date='Adopted February 2013; February 21, 2013',authority='Ashtabula County Auditor GIS',approval_nov2026='not established',defect='right-edge text clipped in native image; no image alteration',sha256=hashlib.sha256((R/'evidence/continued/ashtabula-pdf.bin').read_bytes()).hexdigest())
raster=dict(county='tuscarawas',path='evidence/coordinator-review/tuscarawas-official-render.png',format='PNG',width=2000,height=2600,authority='Tuscarawas County GIS official BOE_Precints MapServer layer 0',vintage='current server render; boundary effective date unknown',approval_nov2026='not established',vector_geometry=False,request_path='evidence/coordinator-review/tuscarawas-render-request.json',metadata_path='evidence/coordinator-review/tuscarawas-official-render.meta.json',sha256=hashlib.sha256((R/'evidence/coordinator-review/tuscarawas-official-render.png').read_bytes()).hexdigest())
w('image-manifest.json',[image,raster])
# All source HTTP observations, including failed alternatives, are first-class evidence.
ledger=[]
for f in sorted((R/'evidence').rglob('*.meta.json')):
 m=json.loads(f.read_text());m['metadata_path']=str(f.relative_to(R));ledger.append(m)
w('source-ledger.json',ledger)
byf=collections.defaultdict(list)
for d in D:byf[d['county_fips']].append(d)
for c in C:
 county=c['county'].lower();ps=[p for p in P if p['county']==county and p['complete_pdf']];gs=[d for d in byf[c['county_fips']] if not d['dataset_id'].startswith('census')]
 c['county_pdf_precinct_files']=sum(p['asset_class']=='precinct-map' for p in ps);c['county_pdf_precinct_pages']=sum(p['page_count'] for p in ps if p['asset_class']=='precinct-map');c['county_pdf_paths']=[p['path'] for p in ps];c['county_pdf_pages']=sum(p['page_count'] for p in ps)
 c['county_image_paths']=[image['path']] if county=='ashtabula' else [raster['path']] if county=='tuscarawas' else []
 c['county_geometry_nonempty_features']=sum(d['feature_count']-d['empty_count'] for d in gs)
 if county in NOTES:c['primary_landing'],c['source_chain'],c['vintage_and_gap']=NOTES[county]
 c['map_approval_nov2026']='not established';c['native_2026_reporting_crosswalk']='not validated'
w('county-inventory.json',C)
# Exact null/invalid units; identifiers and complete attributes retained, without fabricated polygons.
gaps=[]
for d in D:
 if d['dataset_id'].startswith('census'):continue
 gj=json.loads(gzip.decompress((R/d['geojson_path']).read_bytes()));dg=j(d['diagnostics_path'])
 if dg['empty_ordinals']:gaps.append(dict(dataset=d['dataset_id'],kind='source record has no geometry',records=[gj['features'][i]['properties'] for i in dg['empty_ordinals']]))
for c in priority:
 gaps.append(dict(county=c['county'],county_fips=c['county_fips'],kind='November 2026 legal approval and native-unit geographic crosswalk not established',native_units_2024=c['native_units_2024'],native_units_2022=c['native_units_2022'],exact_native_unit_records='reporting-unit-compatibility.csv.gz',details=c['vintage_and_gap']))
t=j('tuscarawas-historical-selection.json');gaps.append(dict(county='Tuscarawas',kind='partial historical official PDF acquisition',catalog_urls=len(t),successful_paths=[x['path'] for x in t if x['status']==200],failed_urls=[dict(url=x['url'],path=x['path']) for x in t if x['status']!=200],warning='archive path number is not a cross-year precinct join'))
gaps.append(dict(county='Richland',kind='official166-page PDF browser-viewable but no downloaded PDF or rendered map',url=NOTES['richland'][0],direct_http_status=403,coordinator_review='Read-only evidence in ../data/map-review; no precinct layer found in examined county public services; not copied or edited by this worker.'))
w('gaps.json',gaps)
w('county-notes.json',{k:dict(primary_url=v[0],chain=v[1],gap=v[2]) for k,v in NOTES.items()})
# Static local links work under file:// without JavaScript or a server.
def a(path,label,download=None):return '<a href="'+h(path,quote=True)+'"'+(' download="'+h(download,quote=True)+'"' if download else '')+'>'+h(label)+'</a>'
def originals(d):
 paths=[]
 if d.get('original_path'):paths.append(d['original_path'])
 paths.extend(d.get('components',{}).values());paths.extend(d.get('batch_paths',[]))
 for k in ['layer_metadata_path','count_path','ids_path','linearized_derivative_path']:
  if d.get(k):paths.append(d[k])
 return list(dict.fromkeys(paths))
def filelink(p):
 b=(R/p).read_bytes()[:4];name=Path(p).name
 if name.endswith('.bin'):name=name[:-4]+('.pdf' if b==b'%PDF' else '.zip' if b[:2]==b'PK' else '.jpg' if b[:2]==b'\xff\xd8' else '.bin')
 return a(p,Path(p).name,name)
head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ohio 2026 • retained precinct map research</title><style>body{font:17px/1.5 system-ui,sans-serif;background:#f4f6f5;color:#17302d;margin:0}main{max-width:1150px;margin:auto;padding:32px}h1{font-size:2.3rem;line-height:1.1}h2{margin:0}a{color:#14635b}p{max-width:95ch}nav{display:flex;flex-wrap:wrap;gap:9px;margin:24px 0}nav a{background:white;border:1px solid #bfd3cd;border-radius:4px;padding:5px 10px}article{background:white;border:1px solid #c6d5d1;border-radius:10px;padding:24px;margin:28px 0;scroll-margin-top:20px}figure{margin:16px 0}figure img{width:100%;max-height:480px;object-fit:contain;background:#eef2ef}figcaption,.muted{font-size:.9rem;color:#53645d}.flag{background:#fff0d9;padding:8px 12px;border-left:4px solid #b47828}li{margin:5px 0}summary{cursor:pointer;font-weight:600;padding:8px 0}code{overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;font-size:.9rem}td,th{padding:8px;text-align:left;border-bottom:1px solid #ddd}footer{padding:30px 0}details{border-top:1px solid #e2e8e5;padding:5px 0}</style><main><h1>Ohio precinct maps</h1><p>November 3, 2026 special U.S. Senate election • unexpired term ending January 3, 2029</p><p class="flag">Research assets, with source defects and historical vintages preserved. No county boundary is certified here for November 2026. No native reporting-unit geographic crosswalk or vote allocation is validated.</p><p>Exact 32 priority counties: 4,581,738 / 5,704,620 2024 Senate votes = 80.3162699707%. All 88 counties are inventoried. Current-published county files, historical originals and Census 2020 statistical VTD references remain distinct. A successful artifact check does not approve boundaries.</p>'''
parts=[head,'<p>'+a('county-inventory.csv','All 88 county inventory CSV')+' · '+a('county-inventory.json','Detailed inventory')+' · '+a('source-ledger.json','HTTP sources, UTC times, headers and hashes')+' · '+a('compatibility-summary.json','Native-ID comparisons')+' · '+a('gaps.json','Exact gaps')+' · '+a('validation.json','Offline validation')+' · '+a('REPRODUCE.md','Reproduce')+'</p>','<p id="census-original">'+filelink('evidence/finaldiscovery/census-state-vtd.bin')+' — one complete official Census 2020 Ohio VTD ZIP, 8,941 features / 88 counties. This is a historical statistical reference, not approved 2026 precincts.</p>','<nav aria-label="Priority counties">']
for c in priority:parts.append(a('#'+c['county'].lower(),str(c['rank'])+' '+c['county']))
parts.append('</nav>')
preferred={'franklin':'franklin-2025','montgomery':'montgomery-2022','butler':'butler-2019','clermont':'clermont-published','mahoning':'mahoning-2025','medina':'medina-wfs','fairfield':'fairfield-published'}
for c in priority:
 county=c['county'].lower();ds=byf[c['county_fips']];gs=[d for d in ds if not d['dataset_id'].startswith('census')];cs=next(d for d in ds if d['dataset_id'].startswith('census'));ps=[p for p in P if p['county']==county and p['complete_pdf']];main=next((d for d in gs if d['dataset_id']==preferred.get(county,county) and d['empty_count']<d['feature_count']),None)
 parts.extend(['<article id="'+county+'" data-fips="'+c['county_fips']+'"><h2>'+str(c['rank'])+'. '+h(c['county'])+'</h2>','<p class="muted">FIPS '+c['county_fips']+' · native county ID '+h(c['county_native_id'])+' · 2024 units '+str(c['native_units_2024'])+' · 2022 units '+str(c['native_units_2022'])+'</p>','<p>'+a(c['primary_landing'],'Primary official route')+' — '+h(c['source_chain'])+'</p>','<p class="flag">'+h(c['vintage_and_gap'])+'</p>'])
 if main:preview=main['preview_path'];caption=main['dataset_id']+' — display-only native-coordinate SVG; original geometry/CRS retained separately.'
 elif county=='tuscarawas':preview=raster['path'];caption='Official GIS server-rendered PNG in native EPSG 3734; raster only, vector queries still omit all 81 geometries.'
 elif county=='ashtabula':preview=image['path'];caption='Official historical JPEG, printed February 2013; actual format differs from catalog title.'
 elif ps and county!='summit':
  show=[p for p in ps if p['asset_class']=='precinct-map'] or ps
  p=next((p for p in show if 'county' in p['label'].lower()),show[0]);preview=p['preview_path'];caption=p['label']+' — first-page raster preview; full original and every-page contact sheet below.'
 else:preview=cs['preview_path'];caption='Census 2020 VTD reference only; county current geometry download gap described above.'
 c['index_preview_path']=preview;parts.append('<figure>'+a(preview,'<preview>').replace('&lt;preview&gt;','<img loading="lazy" src="'+h(preview,quote=True)+'" alt="'+h(c['county']+' map preview',quote=True)+'">')+'<figcaption>'+h(caption)+'</figcaption></figure>')
 for d in gs:
  parts.append('<details><summary>'+h(d['dataset_id'])+' · '+str(d['feature_count'])+' records · '+h(d['vintage'])+'</summary><p>'+str(d['empty_count'])+' empty; '+str(d['invalid_count'])+' invalid; '+str(d['overlap_count'])+' positive-area overlap pairs. These are diagnostics, not approval. '+a(d['diagnostics_path'],'Full source attributes, ID uniqueness and defects')+'</p><p>CRS '+h(str(d['crs_authority']))+' · native extent '+h(str(d['extent_native']))+'</p><p>'+a(d['preview_path'],'SVG preview')+' · '+a(d['geojson_path'],'Derived CRS84 GeoJSON (gzip)')+' · '+a(d['url'],'Official service/publication')+'</p><p>Retained original files and query evidence:</p><ul>')
  for path in originals(d):parts.append('<li>'+filelink(path)+'</li>')
  parts.append('</ul></details>')
 if ps:
  parts.append('<details><summary>'+str(len(ps))+' complete PDF files / '+str(sum(p['page_count'] for p in ps))+' pages — originals and previews</summary><ul>')
  for p in ps:parts.append('<li>'+a(p['path'],p['label'],county+'-'+Path(p['path']).stem+'.pdf')+' · '+str(p['page_count'])+' pages · '+h(p['asset_class'])+' · '+a(p['contact_path'],'every-page contact sheet')+' · '+a(p['preview_path'],'page 1')+' · '+a(p['url'],'source')+'<br><span class="muted">'+h(p['vintage'])+'; '+h('; '.join(p.get('date_lines',[])[:4]))+'</span></li>')
  parts.append('</ul></details>')
 if county=='tuscarawas':parts.append('<p>'+a(raster['path'],'Original county GIS server-rendered PNG','tuscarawas-official-render.png')+' · '+a(raster['metadata_path'],'Exact source URL / UTC / headers / hashes')+' · '+a(raster['request_path'],'Export parameters and native extent')+'</p>')
 if county=='ashtabula':parts.append('<p>'+a(image['path'],'Original precinct JPEG','ashtabula-precincts-2013.jpg')+' · '+a('image-manifest.json','Image format/defect metadata')+'</p>')
 if county=='mahoning':parts.append('<p>'+filelink('evidence/finaldiscovery/mahoning-current.bin')+' — undated original Voting_Precincts ZIP without PRJ, preserved without reprojection.</p>')
 parts.append('<details><summary>Separate Census 2020 historical reference · '+str(cs['feature_count'])+' VTDs</summary><p>'+a(cs['preview_path'],'Reference preview')+' · '+a(cs['geojson_path'],'Derived reference GeoJSON (gzip)')+' · '+a('#census-original','Shared complete statewide original')+' · '+a(cs['diagnostics_path'],'Diagnostics')+'</p></details></article>')
parts.append('<footer>Offline static index. Original .bin responses download with an appropriate suggested extension; .gz evidence is lossless compression of source responses. No external scripts, tiles, collector or calibration are required or claimed.</footer></main></html>')
(R/'index.html').write_text('\n'.join(parts));w('county-inventory.json',C)
import csv,io
stream=io.StringIO(newline='');writer=csv.DictWriter(stream,fieldnames=list(C[0]));writer.writeheader();writer.writerows({k:(json.dumps(v,separators=(',',':')) if isinstance(v,(list,dict)) else v) for k,v in c.items()} for c in C);(R/'county-inventory.csv').write_text(stream.getvalue())
# A short machine-readable coverage statement prevents publication/current/approval conflation.
summary=dict(priority_counties=32,inventory_counties=88,native_units_2024=8878,native_units_2022=8933,census_statewide_features=8941,county_gis_datasets=28,county_gis_counties_nonempty=len({d['county'] for d in D if not d['dataset_id'].startswith('census') and d['empty_count']<d['feature_count']}),complete_pdf_files=sum(p['complete_pdf'] for p in P),complete_pdf_pages=sum(p.get('page_count',0) for p in P if p['complete_pdf']),supplemental_pdf_files=sum(p['complete_pdf'] and p['asset_class']!='precinct-map' for p in P),county_precinct_download_gap=['Richland'],approved_2026_counties=0,validated_2026_crosswalk_counties=0)
w('coverage-summary.json',summary)
# Assigned narrative report: all figures come from manifests, not assumptions about map topology.
report=['# Ohio precinct maps — November 3, 2026 special Senate election','', 'The election fills the unexpired U.S. Senate term ending January 3, 2029. **Research package complete with explicit access and geometry gaps; no November 2026 boundary approval or native-unit geographic crosswalk is established.** Open the [offline map index](maps/index.html) for actual downloads and usable previews for every priority county.','',f"The package inventories all **88 counties**, retains one complete official Census 2020 Ohio VTD ZIP (**8,941 features**), and derives separate reference previews for the exact **32 priority counties**. County/municipal sources supply **{summary['county_gis_counties_nonempty']} counties with nonempty GIS geometry**, **{summary['complete_pdf_files']} complete PDFs / {summary['complete_pdf_pages']} pages**, and one historical precinct JPEG plus a verified official Tuscarawas GIS server-rendered PNG (raster only). The PDF count includes two ward/school supplements and one historical council map with precinct outlines; these are not counted as current precinct packages. Richland has no retained county precinct map download; browser viewability is not counted as a downloaded asset.",'', 'The exact priority order comes from [priority-set.json](data/turnout/priority-set.json): 4,581,738 / 5,704,620 all-seven-candidate 2024 Senate votes = **80.3162699707%**. The first 31 total 4,542,798; the top 15 total 3,525,320. All five separate volume measures select the same membership. The read-only county-turnout SHA-256 remains `d9133f7f88eca91b8bef8f3987b3e1abfb30b19e61d1d824a1e270dde4049a90`.','', '## Retained county assets and exact coverage','', 'Counts below are source features/pieces or PDF pages, not a claim that each feature is one election reporting unit. Census references are kept separate from county publications. Every row has a preview and download links in the index.','', '| Rank | County / FIPS | Native units 2024 / 2022 | County GIS records by vintage | Complete county PDFs / pages |','|---:|---|---:|---|---:|']
for c in priority:
 gs=[d for d in byf[c['county_fips']] if not d['dataset_id'].startswith('census')];ps=[p for p in P if p['county']==c['county'].lower() and p['complete_pdf']];g='; '.join(d['dataset_id']+': '+str(d['feature_count'])+(' ('+str(d['empty_count'])+' empty)' if d['empty_count'] else '') for d in gs) or ('2013 JPEG' if c['county']=='Ashtabula' else 'none')
 report.append('| '+str(c['rank'])+' | ['+c['county']+'](maps/index.html#'+c['county'].lower()+') / '+c['county_fips']+' | '+str(c['native_units_2024'])+' / '+str(c['native_units_2022'])+' | '+g+' | '+str(len(ps))+' / '+str(sum(p['page_count'] for p in ps))+' |')
report.extend(['','## Primary provenance and vintage limitations','', 'The [88-county inventory](maps/county-inventory.json) includes native county IDs, FIPS, both reporting counts, Census IDs/counts and official BOE URLs from the [Secretary of State directory](https://www.ohiosos.gov/directories/county-boards-of-elections). The directory was retained as browser-rendered evidence because direct origin requests were blocked. Shared-host 403 bodies are retained as failed observations, never passed off as map assets. [Source ledger](maps/source-ledger.json) records exact requested/final URLs, UTC retrieval times, HTTP status/headers and content/stored SHA-256; acquisition scripts retain official landing, catalog, app, webmap and service responses. The generic initial BOE route probes are explicitly separate from canonical directory URLs.',''])
for c in priority:
 u,chain,gap=NOTES[c['county'].lower()];report.extend(['**'+c['county']+'** — [official primary route]('+u+'). '+chain+' '+gap,''])
report.extend(['## Compatibility with reconciled native units','', '[reporting-unit-compatibility.csv.gz](maps/reporting-unit-compatibility.csv.gz) retains **all 8,878 native 2024 and 8,933 native 2022 records**, including their exact native county IDs/FIPS, unit keys, names and codes. Its identities are independently checked against the priority dispatch constituents; none is dropped for a missing, blank, reused or administrative identifier. [compatibility-summary.json](maps/compatibility-summary.json) compares each of 28 county GIS datasets separately with each historical roster (56 comparisons), listing every unmatched native value, extra source value, blank and reused identifier. Exact strings are inventory evidence only, not a crosswalk. Generic OBJECTID, source ordinal, Census VTD number, PDF number and cross-year numeric equality are never used for vote allocation.','', 'Source topology differs materially: Clermont 344 pieces / 168 STATEID values; Fairfield 133 pieces / 111 SOS_CODE values; Clark 78 pieces / 76 letter codes; Columbiana 135 pieces with blank/reused codes; Medina 203 polygons without attributes or identifiers; Geauga 80 records with City of Chardon D-23 absent geometry; Tuscarawas 81 records with every geometry absent. Exact source attributes for empty/invalid records, and the partial Tuscarawas historical PDF success/failure inventory, are in [gaps.json](maps/gaps.json) and per-dataset diagnostics. A source ordinal only locates an unchanged record; it is never labeled a precinct ID.','', 'The 2024/2022 result files do not establish future boundaries. County certified summaries retain 640 Senate 2024, 2,771 presidential 2024 and 1,739 Senate 2022 write-in votes omitted from raw precinct candidate headers. These remain unallocated county residuals; no method counts, polygons, administrative-unit geography or precinct write-in allocations are inferred. No validated 2026 reporting roster or historical-to-2026 geographic crosswalk was found.','', '## Geometry, pagination and artifact validation','', 'Every ArcGIS layer is queried for count and all object IDs, then complete batches of at most 50 IDs with all attributes, native spatial reference and `returnTrueCurves=true`. Count, unique ID set and returned batch identities must agree; transfer-limit flags fail acquisition. Countywide services used by a city app are retrieved without an app city filter. Medina WFS unbounded and high-limit results agree byte-for-byte with 203 hits; a 10-feature control confirms the limit behavior. Census original covers all 88 FIPS and is stored once.','', 'Original ZIPs/components, native EsriJSON (including true curves and SR metadata), GML and PDFs/images are unchanged. Lossless gzip is explicit in metadata. Derived GeoJSON reprojects XY to CRS84 with full ring vertex counts and no simplification; native Z/M/curves remain in originals. Clark (2), Stark (9), Licking (2) and Greene (86) true-curve records use separately retained server-linearized rings for polygon-only derivatives. SVG previews fit native coordinates and round display positions only. The undated Mahoning ZIP lacks PRJ and is not reprojected.','', 'Diagnostics test empty and invalid/self-intersecting geometry, nonfinite extents, all positive-area polygon overlaps, intersection errors and every attribute field’s blank/unique/reused values. Invalid source geometry is not repaired; no sliver cutoff silently removes overlap evidence. Some overlaps are tiny coordinate slivers or source split/overlay pieces; the full pair areas in native CRS squared units remain available for review. These checks cannot certify legal completeness or approval. PDF originals are checked for complete EOF and repair-free parsing; truncated historical captures are excluded. Each complete PDF has every page represented in a contact sheet, plus a larger first-page preview. Ashtabula’s actual JPEG format and original clipping defect are explicit.','', '[validation.json](maps/validation.json) and [artifact-manifest.json](maps/artifact-manifest.json) record the independent offline audit: hashes/ZIP CRCs, native counts and ID sets, all 17,811 historical unit identities, exact priority order/FIPS, geometry/vertex preservation, PDF manifests and local index links. Every individual retained file is below 40,000,000 bytes. See [REPRODUCE.md](maps/REPRODUCE.md) for rebuilding and auditing without refetching or modifying the original snapshot. Installed dependencies/caches are excluded.','', 'No live collector, map approval, calibration, turnout model or precinct vote allocation is claimed.'])
